const storyBeats=[
 {date:'GOTHAM CITY · 1982',title:'A night at the movies',text:'<p>After a late show, <strong>Thomas and Martha Wayne</strong> walk home with their young son, Bruce. The city is all wet pavement and distant sirens.</p><p>An old gunman steps out of the alley. He demands money. Thomas gives him <strong>$200</strong>—everything at hand.</p><p class="quote">“Take it. Just let my family go.”</p>'},
 {date:'GOTHAM CITY · THAT NIGHT',title:'The promise',text:'<p>The gunman fires. Thomas and Martha fall. Bruce is left alone beneath the streetlights, crying beside the two people he loved most.</p><p>In the silence that follows, grief becomes a promise: <strong>no one else should have to feel this helpless.</strong></p>'},
 {date:'GOTHAM CITY · 2008',title:'A fortune, a house, a name',text:'<p>Twenty-six years later, Bruce discovers <strong>$1 billion</strong> his father had tucked into his jacket pocket—seed money from a plan Thomas never got to finish.</p><p>Bruce invests it, buys an old mansion, and gives his growing operation a name: <strong>Wayne Enterprises.</strong> The grand rooms fill with friends and parties. Harvey Dent is among them—a bright promise for Gotham.</p>'},
 {date:'GOTHAM CITY · 2009',title:'A face changed',text:'<p>A year later, a terrible incident leaves <strong>Harvey Dent’s face scarred</strong> and his life changed. Gotham’s shining future feels suddenly fragile.</p><p>Bruce retreats from the parties. With luggage in hand, he descends into a forgotten cave beneath the estate.</p>'},
 {date:'WAYNE CAVE · THREE MONTHS LATER',title:'An unexpected ally',text:'<p>“Excuse me, sir. Are you looking for something? There’s nothing in here. It’s old—just like me.”</p><p>“I’m trying to do something with this place. What makes you think you can tell me what to do?”</p><p>“I understand you’re standing your ground. But you are trespassing.” Bruce refuses to leave. The old man eventually walks away.</p><p>Three months pass. Then he returns: <strong>“Excuse me, sir. Remember me? I’m Alfred.”</strong></p>'},
 {date:'A FEW MONTHS LATER · NOW',title:'The cave is ready',text:'<p>“What are you doing here?” Bruce asks.</p><p>“I’m trying to help you make this cave,” Alfred replies. Together they build a computer station, a suit bay, the Batmobile, and an elevator to the estate.</p><p>Alfred adds batarangs, smoke pellets, a grapple gun—and one last gift: a book on self-defense. <strong>Tonight, the work begins.</strong></p>'}
];let beat=0;

